'use strict';

// MODULES //

import isnan from '@stdlib/math-base-assert-is-nan';
import incrmmin from '@stdlib/stats-incr-mmin';


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving minimum value, ignoring `NaN` values.
*
* @param {PositiveInteger} W - window size
* @throws {TypeError} must provide a positive integer
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmmin( 3 );
*
* var m = accumulator();
* // returns null
*
* m = accumulator( 2.0 );
* // returns 2.0
*
* m = accumulator( NaN );
* // returns 2.0
*
* m = accumulator( -5.0 );
* // returns -5.0
*
* m = accumulator( 3.0 );
* // returns -5.0
*
* m = accumulator( 5.0 );
* // returns -5.0
*
* m = accumulator();
* // returns -5.0
*/
function incrnanmmin( W ) {
	var acc = incrmmin( W );
	return accumulator;

	/**
	* If provided a value, the accumulator function returns an updated moving minimum. If not provided a value, the accumulator function returns the current moving minimum.
	*
	* @private
	* @param {number} [x] - input value
	* @returns {(number|null)} moving minimum or null
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 ) {
			return acc();
		}
		if ( isnan( x ) ) {
			return acc();
		}
		return acc( x );
	}
}


// EXPORTS //

export default incrnanmmin;
